export function getCurriculumPlanByGrade(grade?: string | GradeLevel) {
  const gradeLevel = typeof grade === 'number' ? grade : parseGradeLevel(grade);
  return curriculumPlans.find((plan) => plan.grade === gradeLevel) ?? curriculumPlans[6];
}

export function getLessonForGrade(grade?: string | GradeLevel): Lesson {
  const gradeLevel = typeof grade === 'number' ? grade : parseGradeLevel(grade);
  return gradeLessons[gradeLevel];
}

export function getGradeProgressLabel(grade?: string) {
  const plan = getCurriculumPlanByGrade(grade);
  return `${plan.label} · ${plan.stage}`;
}
